{#-
	Manav Modern Quotation: print format of ERPNext's Quotation in the modern black and white
	layout (the default print format of Quotation, set in manav/manav/erpnext_fields.py).

	Working: the layout itself is the file
	manav/templates/print_formats/manav_modern_quotation_body.html, which is shared with the
	print format of the old quotations (Manav Modern Quotation Head). This print format only
	gathers the values of a Quotation into the variable `q`, in the shape that file describes,
	and then includes it:
	- machines are the lines that are not options; the options of a machine are the lines whose
	  "Option of Item" is the machine's code;
	- a machine's picture is the Image of its quotation line (ERPNext copies it from the Item when
	  the item is chosen), else the Image of the Item, for lines made before the Item had one;
	- amounts are formatted by ERPNext in the quotation's currency;
	- the reference fields are the customer's reference and its date, the sales engineer and the
	  Haas Cust ID; all four are passed on, filled or not, and printed with their names;
	- payment info is the payment schedule and the "valid till" date, when filled;
	- the signing person is the sales person in "Signed By", with the designation from Employee
	  Master through the sales person's old employee code.

	Created: 2026-10-13.

	CHANGE NOTE
	Date: 2026-10-13
	Change: The layout was moved out of this print format into the shared file named above;
	this print format keeps only the gathering of the values. The page it prints is unchanged.
	Reason: The user asked for the new layout on all quotations, which includes the old ones in
	Quotation Head; one shared layout keeps the two from drifting apart. The earlier changes of
	this day are listed in the shared file.

	CHANGE NOTE
	Date: 2026-10-14
	Change: The picture of each machine is passed on to the shared layout.
	Reason: The user asked for the image of the item on the quotation.

	CHANGE NOTE
	Date: 2026-10-14
	Change: A line without Specifications of its own prints the Specifications of its Item.
	Reason: Specifications are copied to a line only when the item is chosen; the user had added
	them to an Item after its quotation line was made, and they did not print.

	CHANGE NOTE
	Date: 2026-10-17
	Change: A line whose "Sub-Item of" is empty is still printed as an option, under its machine,
	when the Quotation Sub Item Master lists its item as a sub-item of another machine line on the
	quotation. So the page shows each machine, then its options, then the next machine, whatever
	order the lines were entered in.
	Reason: The user's quotation had an option (ACF) added as an ordinary line; it printed as a
	machine of its own, with a specification box, above the machine it belongs to.
-#}
{#- a sales person whose name was taken already is stored as "NAME (CODE)"; the code is not printed -#}
{%- macro person(name) -%}{{ (name or "").split(" (")[0] }}{%- endmacro -%}
{%- set lines = doc.get("items") or [] -%}
{#- Lines marked "Sub-Item of" are options. An unmarked line is an option too when the Quotation
    Sub Item Master lists its item as a sub-item of another unmarked line's item, and its own item
    is not a machine there (has no sub-items). Codes are compared without case, as the database
    does. parent_of: line idx -> item code of its machine. -#}
{%- set unmarked = lines | rejectattr("custom_main_item_code") | list -%}
{%- set unmarked_codes = unmarked | map(attribute="item_code") | select | list -%}
{%- set sub_links = frappe.get_all("Quotation Sub Item Master", filters={"main_item_code": ["in", unmarked_codes]}, fields=["main_item_code", "sub_item_code"]) if unmarked_codes else [] -%}
{%- set link_keys = [] -%}
{%- set machine_keys = [] -%}
{%- for link in sub_links -%}
	{%- set _ = link_keys.append((link.main_item_code or "") | lower ~ "::" ~ (link.sub_item_code or "") | lower) -%}
	{%- set _ = machine_keys.append((link.main_item_code or "") | lower) -%}
{%- endfor -%}
{%- set parent_of = {} -%}
{%- for line in unmarked -%}
	{%- set code = (line.item_code or "") | lower -%}
	{%- if code and code not in machine_keys -%}
		{%- for machine in unmarked -%}
			{%- if line.idx not in parent_of and machine.idx != line.idx and ((machine.item_code or "") | lower ~ "::" ~ code) in link_keys -%}
				{%- set _ = parent_of.update({line.idx: machine.item_code}) -%}
			{%- endif -%}
		{%- endfor -%}
	{%- endif -%}
{%- endfor -%}
{%- set main_items = unmarked | rejectattr("idx", "in", parent_of.keys() | list) | list -%}
{%- set main_codes = main_items | map(attribute="item_code") | list -%}
{%- set signer_code = frappe.db.get_value("Sales Person", doc.custom_signed_by, "custom_employee_code") if doc.custom_signed_by else None -%}
{%- set contact_designation = frappe.db.get_value("Contact", doc.contact_person, "designation") if doc.contact_person else None -%}

{%- set q = {
	"company": doc.company,
	"date": frappe.utils.getdate(doc.transaction_date) if doc.transaction_date else None,
	"number": doc.name,
	"customer_name": doc.customer_name or doc.party_name,
	"address": doc.address_display,
	"attn": (doc.contact_display ~ ((", " ~ contact_designation) if contact_designation else "")) if doc.contact_display else "",
	"phone": doc.contact_mobile,
	"issuer_address": doc.company_address_display,
	"refs": [],
	"notes": [],
	"machines": [],
	"loose_options": [],
	"subtotal": doc.get_formatted("net_total"),
	"taxes": [],
	"grand_total": doc.get_formatted("grand_total"),
	"payment": [],
	"terms": doc.terms,
	"signer": person(doc.custom_signed_by) | trim,
	"designation": frappe.db.get_value("Employee Master", signer_code, "designation") if signer_code else None,
} -%}

{#- the four reference fields of the old quotation header; all are given, filled or not -#}
{%- set _ = q.refs.extend([
	["Ref. No.", doc.custom_your_reference],
	["Ref Dt.", frappe.utils.getdate(doc.custom_your_reference_date).strftime("%d/%m/%y") if doc.custom_your_reference_date else ""],
	["Sales Engg.", person(doc.custom_sales_engineer) | trim],
	["Cust ID", doc.custom_haas_customer_id],
]) -%}

{#- machines with their options, then the options whose machine is not on the quotation -#}
{%- for item in main_items -%}
	{%- set options = [] -%}
	{%- for option in lines if option.custom_main_item_code == item.item_code or parent_of.get(option.idx) == item.item_code -%}
		{%- set _ = options.append({"code": option.item_code, "name": option.item_name, "description": option.description, "rate": option.get_formatted("rate", doc), "qty": option.get_formatted("qty", doc), "amount": option.get_formatted("amount", doc)}) -%}
	{%- endfor -%}
	{#- the picture copied to the line when the item was chosen, else the Item's picture now -#}
	{%- set image = item.image or (frappe.db.get_value("Item", item.item_code, "image") if item.item_code else None) -%}
	{#- The line's own Specifications, copied from the Item when the item was chosen. A line made
	    before the Item had any has none: the Item's Specifications are used then. -#}
	{%- set spec_text = item.custom_specifications or (frappe.db.get_value("Item", item.item_code, "custom_specifications") if item.item_code else None) -%}
	{%- set _ = q.machines.append({"code": item.item_code, "name": item.item_name, "image": image, "spec_text": spec_text, "description": item.description, "rate": item.get_formatted("rate", doc), "qty": item.get_formatted("qty", doc), "amount": item.get_formatted("amount", doc), "options": options}) -%}
{%- endfor -%}
{%- for option in lines | selectattr("custom_main_item_code") | rejectattr("custom_main_item_code", "in", main_codes) -%}
	{%- set _ = q.loose_options.append({"code": option.item_code, "name": option.item_name, "description": option.description, "rate": option.get_formatted("rate", doc), "qty": option.get_formatted("qty", doc), "amount": option.get_formatted("amount", doc)}) -%}
{%- endfor -%}

{#- the taxes that have an amount -#}
{%- for tax in (doc.get("taxes") or []) | selectattr("tax_amount") -%}
	{%- set _ = q.taxes.append([(tax.description or tax.account_head or "Tax") ~ ((" @ " ~ ("%g" | format(tax.rate)) ~ "%") if frappe.utils.flt(tax.rate) else ""), tax.get_formatted("tax_amount", doc)]) -%}
{%- endfor -%}

{#- payment schedule and validity -#}
{%- for row in doc.get("payment_schedule") or [] -%}
	{%- set _ = q.payment.append("<b>" ~ (row.payment_term or row.description or "Payment") ~ ":</b>" ~ ((" " ~ ("%g" | format(row.invoice_portion)) ~ "%") if frappe.utils.flt(row.invoice_portion) else "") ~ ((" " ~ row.description) if row.description and row.payment_term and row.description != row.payment_term else "")) -%}
{%- endfor -%}
{%- if doc.valid_till -%}{%- set _ = q.payment.append("<b>Valid till:</b> " ~ frappe.utils.getdate(doc.valid_till).strftime("%d.%m.%Y")) -%}{%- endif -%}

{% include "manav/templates/print_formats/manav_modern_quotation_body.html" %}
